import Foundation
enum BudgetStatus: String, Codable, Equatable, Sendable { case planned, quoted, booked, paid }
struct BudgetItem: Codable, Equatable, Sendable, Identifiable { let id:UUID;let weddingID:UUID;let category:String?;let name:String;let estimatedAmount:Double?;let actualAmount:Double?;let paidAmount:Double?;let status:BudgetStatus?;let relatedVendorID:UUID?;let notes:String?;let createdAt:Date
enum CodingKeys:String,CodingKey{case id;case weddingID="wedding_id";case category;case name;case estimatedAmount="estimated_amount";case actualAmount="actual_amount";case paidAmount="paid_amount";case status;case relatedVendorID="related_vendor_id";case notes;case createdAt="created_at"}}
struct BudgetItemDraft:Codable,Equatable,Sendable{let category:String?;let name:String;let estimatedAmount:Double?;let actualAmount:Double?;let paidAmount:Double?;let status:BudgetStatus?;let relatedVendorID:UUID?;let notes:String?;enum CodingKeys:String,CodingKey{case category;case name;case estimatedAmount="estimated_amount";case actualAmount="actual_amount";case paidAmount="paid_amount";case status;case relatedVendorID="related_vendor_id";case notes}}
struct BudgetItemPatch:Codable,Equatable,Sendable{let category:String?;let name:String?;let estimatedAmount:Double?;let actualAmount:Double?;let paidAmount:Double?;let status:BudgetStatus?;let relatedVendorID:UUID?;let notes:String?;var isEmpty:Bool{category==nil&&name==nil&&estimatedAmount==nil&&actualAmount==nil&&paidAmount==nil&&status==nil&&relatedVendorID==nil&&notes==nil};enum CodingKeys:String,CodingKey{case category;case name;case estimatedAmount="estimated_amount";case actualAmount="actual_amount";case paidAmount="paid_amount";case status;case relatedVendorID="related_vendor_id";case notes}}
